namespace CSharpPracticum.Tasks.Level2;
internal class Task20_Generics:ITask{public string Title=>"Задание 20: Обобщения Swap и Max";public string Description=>"Реализовать обобщённые Swap<T> и Max<T>.";public string[] Requirements=>new[]{"Swap<T>(ref T a, ref T b) без ограничений.","Max<T> с ограничением IComparable<T>.","Показать на int, string и double."};private static void Swap<T>(ref T a,ref T b)=>(a,b)=(b,a);private static T Max<T>(T a,T b) where T:IComparable<T> => a.CompareTo(b)>=0?a:b;public void Run(){int a=1,b=2;Swap(ref a,ref b);Console.WriteLine($"int swap={a},{b}; max={Max(a,b)}");string x="a",y="z";Swap(ref x,ref y);Console.WriteLine($"string swap={x},{y}; max={Max(x,y)}");double c=1.2,d=3.4;Swap(ref c,ref d);Console.WriteLine($"double swap={c},{d}; max={Max(c,d)}");}}
